def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_factors(num):
    factors = []
    for i in range(2, num + 1):
        if num % i == 0 and is_prime(i):
            factors.append(i)
    return factors

def is_multiply_prime(a):
    if a >= 100:
        return False
    factors = prime_factors(a)
    if len(factors) == 3:
        return True
    return False

